import * as T from './vendor/three.module.js';
import {World as BaseWorld} from './world.js';
import {HospitalWorld} from './hso-world.js?v=3.1.0';
import {CAREERS,EXCUSES,aimTarget,clamp} from './rally-rules.js?v=3.1.0';
const up=new T.Vector3(0,1,0),mat=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.65,...extra});
const boxG=new T.BoxGeometry(1,1,1),ballG=new T.IcosahedronGeometry(1,1);
function part(root,geometry,material,x,y,z,sx=1,sy=1,sz=1){const mesh=new T.Mesh(geometry,material);mesh.position.set(x,y,z);mesh.scale.set(sx,sy,sz);mesh.castShadow=true;root.add(mesh);return mesh;}
function label(text,{bg='#112937',fg='#f4f4dd',width=768,height=192,size=42}={}){const c=document.createElement('canvas');c.width=width;c.height=height;const ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.beginPath();ctx.roundRect(3,3,width-6,height-6,18);ctx.fill();ctx.strokeStyle=fg;ctx.lineWidth=4;ctx.stroke();ctx.fillStyle=fg;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`700 ${size}px Arial,sans-serif`;let lines=[''];for(const word of text.split(' ')){const i=lines.length-1,test=(lines[i]+' '+word).trim();if(ctx.measureText(test).width>width-40)lines.push(word);else lines[i]=test;}lines.forEach((line,i)=>ctx.fillText(line,width/2,height/2+(i-(lines.length-1)/2)*(size+7)));const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const sprite=new T.Sprite(new T.SpriteMaterial({map:texture,depthWrite:false}));sprite.scale.set(16,height/width*16,1);return sprite;}
function makeTroll(excuse,i){const root=new T.Group(),skin=mat([0x91a768,0x739d85,0x9a9b72][i%3]),coat=mat([0x454667,0x735850,0x435b69][i%3]),dark=mat(0x17242d),ivory=mat(0xf4e9c4),white=mat(0xf4ffed);root.userData.skin=skin;root.userData.base=skin.color.clone();
 part(root,ballG,coat,0,2.0,0,1.65,1.9,1.1);part(root,ballG,skin,0,4.2,0,1.5,1.4,1.15);part(root,ballG,skin,0,4.05,1.25,.55,.62,.8);
 for(const side of [-1,1]){part(root,ballG,coat,side*1.8,2.45,0,.65,1.2,.6);part(root,ballG,skin,side*2.03,1.55,.1,.65,.65,.65);part(root,boxG,dark,side*.8,.6,0,.9,1.2,1);part(root,ballG,dark,side*.8,.24,.4,.85,.38,1.05);part(root,ballG,white,side*.55,4.65,.95,.4,.35,.25);part(root,ballG,dark,side*.53,4.64,1.15,.14,.2,.1);const horn=part(root,new T.ConeGeometry(.35,1.2,6),ivory,side*1.2,5.35,0);horn.rotation.z=-side*.5;}
 part(root,boxG,ivory,0,3.75,1.13,.75,.14,.12);part(root,boxG,mat(0xe7c26c),1.75,1.5,.75,1.3,.95,.2);
 const tag=label(excuse);tag.position.y=7.3;tag.material.depthTest=false;root.add(tag);root.userData.tag=tag;return root;
}
function makeCannon(car){const root=new T.Group();root.position.y=1.8;const blue=mat(0x4bd4ec,{metalness:.35,roughness:.28}),white=mat(0xf6f2dd),orange=mat(0xf1b456),navy=mat(0x193b50);part(root,new T.CylinderGeometry(.62,.7,.24,12),navy,0,.1,0);const swivel=new T.Group();swivel.position.y=.28;root.add(swivel);part(swivel,boxG,white,0,.2,0,.8,.5,1.0);const barrel=part(swivel,new T.CylinderGeometry(.19,.25,1.8,12),blue,0,.25,-1.1);barrel.rotation.x=Math.PI/2;const nozzle=part(swivel,new T.TorusGeometry(.24,.075,8,12),orange,0,.25,-2.04);part(swivel,ballG,blue,0,.22,-2.04,.12,.12,.06);const tank=part(root,new T.CylinderGeometry(.44,.44,1.5,12),blue,0,.28,1.13);tank.rotation.z=Math.PI/2;part(root,boxG,white,0,.31,1.6,.5,.4,.12);root.userData.swivel=swivel;root.userData.barrel=barrel;root.userData.nozzle=nozzle;car.add(root);return root;}
function makeRocket(car){const root=new T.Group(),paper=mat(0xeee4c6),red=mat(0xc96148),ink=mat(0x24344a),gold=mat(0xf3ba52,{emissive:0xc05812,emissiveIntensity:.5});const body=part(root,new T.CylinderGeometry(.77,.77,4.8,12),paper,0,1,4);body.rotation.x=Math.PI/2;const cone=part(root,new T.ConeGeometry(.8,1.7,12),red,0,1,.75);cone.rotation.x=-Math.PI/2;
 for(const side of [-1,1]){const fin=part(root,boxG,red,side*.9,1,5.9,.14,1.5,1.8);fin.rotation.z=side*.6;part(root,boxG,ink,side*.65,.6,2.2,.2,.25,1.2);}
 const band=part(root,new T.CylinderGeometry(.8,.8,.4,12),ink,0,1,4.6);band.rotation.x=Math.PI/2;const stamp=label('ARKIVRAKETT',{width:512,height:96,size:38,bg:'#eee4c6',fg:'#a34831'});stamp.position.set(0,2.3,4.1);stamp.scale.set(4.3,.8,1);root.add(stamp);
 const flame=new T.Group();for(let i=0;i<2;i++){const f=part(flame,new T.ConeGeometry(i?.4:.75,i?3:4.5,9),i?paper:gold,0,1,i?7.75:8.5);f.rotation.x=Math.PI/2;}root.add(flame);root.userData.flame=flame;root.visible=false;car.add(root);return root;
}
class RallyScene{
 constructor(world){this.world=world;this.root=new T.Group();world.scene.add(this.root);this.trolls=Array.from({length:12},(_,i)=>{const t=makeTroll(EXCUSES[(i+['fjord','pass','aurora'].indexOf(world.track.config.id)*5)%EXCUSES.length],i);t.visible=false;this.root.add(t);return t;});this.cannon=makeCannon(world.car);this.rocket=makeRocket(world.car);
 this.droplets=new T.InstancedMesh(new T.SphereGeometry(.18,7,5),new T.MeshBasicMaterial({color:0x7aedff,transparent:true,opacity:.92}),160);this.droplets.frustumCulled=false;this.droplets.instanceMatrix.setUsage(T.DynamicDrawUsage);world.scene.add(this.droplets);this.dummy=new T.Object3D();this.lastShot=0;this.recoil=0;
 const geo=new T.BufferGeometry(),positions=[];let seed=517;const rand=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);const end=world.track.position(world.track.length+50);
 for(let i=0;i<1400;i++)positions.push(end.x+(rand()-.5)*5000,end.y+200+rand()*3500,end.z+(rand()-.5)*5000);geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));this.stars=new T.Points(geo,new T.PointsMaterial({color:0xffedc7,size:4,sizeAttenuation:true,transparent:true,opacity:0,depthWrite:false,fog:false}));world.scene.add(this.stars);
 this.space=new T.Group();this.space.visible=false;world.scene.add(this.space);this.papers=[];
 for(let i=0;i<18;i++){const g=new T.Group(),paper=mat(0xf1e4c2),navy=mat(0x3c5362);part(g,boxG,paper,0,0,0,2.3,3.2,.1);part(g,boxG,navy,0,.8,.07,1.5,.12,.02);part(g,boxG,navy,-.2,.2,.07,1.1,.09,.02);part(g,boxG,navy,-.3,-.3,.07,.9,.09,.02);const f=world.track.at(world.track.length+50);g.position.copy(f.p).addScaledVector(f.r,(i%2?1:-1)*(8+rand()*12)).addScaledVector(f.t,(rand()-.5)*25);g.position.y+=35+i*85;g.rotation.set(rand(),rand()*3,rand()-.5);g.userData.phase=rand()*6;this.space.add(g);this.papers.push(g);}
 for(let i=0;i<6;i++){const c=CAREERS[i],beacon=label('★'.repeat(c.stars)+'  '+c.name,{width:768,height:160,size:42,bg:'#172943',fg:'#f6d086'});beacon.position.copy(world.track.position(world.track.length+55,13,c.height));beacon.scale.set(17,3.54,1);this.space.add(beacon);}
 this.dome=world.scene.children.find(o=>o.material?.uniforms?.top);this.domeTop=this.dome?.material.uniforms.top.value.clone();this.domeBottom=this.dome?.material.uniforms.bottom.value.clone();this.skyStart=new T.Color(world.track.config.sky);this.fogStart=new T.Color(world.track.config.fog);this.night=new T.Color(0x091226);
 }
 update(state,dt,mode,game,options){const w=this.world,flight=['finish','results'].includes(mode),age=state.rocketAge||0;
 this.rocket.visible=flight;this.rocket.position.x=flight?Math.max(0,1-age/.9)*12:0;this.rocket.userData.flame.visible=flight&&age>1.65&&age<11.8;this.rocket.userData.flame.scale.set(1,1,options.motion===false?1:1+Math.sin(age*23)*.1);this.space.visible=flight;
 const fade=flight?clamp((state.air-55)/450,0,1):0;w.scene.background.copy(this.skyStart).lerp(this.night,fade);w.scene.fog.color.copy(this.fogStart).lerp(this.night,fade);w.scene.fog.density=.00038+fade*.0026;this.stars.material.opacity=fade;if(this.dome){this.dome.material.uniforms.top.value.copy(this.domeTop).lerp(this.night,fade);this.dome.material.uniforms.bottom.value.copy(this.domeBottom).lerp(this.night,fade);}
 for(const p of this.papers){if(options.motion!==false)p.rotation.z+=dt*.15;}
 const target=game?aimTarget(game,state):null;this.cannon.userData.swivel.rotation.y=target?-clamp(Math.atan2(target.x-state.x,target.s-state.s)-state.heading,-.25,.25):0;
 if(game&&game.nextShot!==this.lastShot){this.lastShot=game.nextShot;this.recoil=.12;}this.recoil=Math.max(0,this.recoil-dt);this.cannon.userData.barrel.position.z=-1.1+this.recoil;
 for(let i=0;i<this.trolls.length;i++){const root=this.trolls[i],t=game?.trolls[i];root.visible=!!t&&!flight&&['race','quiz','paused','countdown'].includes(mode)&&t.phase!=='sleep'&&t.s-state.s<210&&state.s-t.s<30&&!(['clear','bump','passed'].includes(t.phase)&&t.age>1.2);if(!root.visible)continue;
 const resolved=['clear','bump','passed'].includes(t.phase),u=resolved?clamp(t.age/1.2,0,1):0;root.position.copy(w.track.position(t.s,t.x,resolved?u*8:0));root.rotation.set(0,-w.track.at(t.s).yaw,resolved?u*1.3:Math.sin((game.time+i)*5)*.045);root.scale.setScalar(resolved?Math.max(.01,1-u):1);root.userData.tag.visible=!resolved;const distance=Math.max(20,t.s-state.s),scale=clamp(distance/60,.85,1.55);root.userData.tag.scale.set(16*scale,4*scale,1);root.userData.skin.color.copy(root.userData.base).lerp(new T.Color(0x9befff),t.flash>0?.85:0);
 }
 let n=0;const set=(s,x,y,scale)=>{if(n>=160)return;this.dummy.position.copy(w.track.position(s,x,y));this.dummy.rotation.set(0,0,0);this.dummy.scale.setScalar(scale);this.dummy.updateMatrix();this.droplets.setMatrixAt(n++,this.dummy.matrix);};
 if(game&&!flight){for(const p of game.shots)for(let j=0;j<5;j++)set(p.s-j*.8,p.x-j*p.vx/130,p.y,1-j*.12);for(const e of game.effects)for(let i=0;i<14;i++){const a=i/14*Math.PI*2,r=e.age*10;set(e.s+Math.cos(a)*r,e.x+Math.sin(a)*r,2.5+Math.sin(i*2.1)*e.age*6-e.age*e.age*3,1.2-e.age);}}
 this.dummy.scale.setScalar(0);this.dummy.updateMatrix();while(n<160)this.droplets.setMatrixAt(n++,this.dummy.matrix);this.droplets.instanceMatrix.needsUpdate=true;
 }
}
export class World extends BaseWorld{
 build(track){super.build(track);this.rally=new RallyScene(this);this.hospitals=new HospitalWorld(this);}
 placeCar(obj,state){const f=super.placeCar(obj,state);if(state.flightPitch!==undefined)obj.rotation.x=state.flightPitch;else{obj.rotation.x+=state.pitch||0;obj.rotation.z+=clamp(state.roll||0,-.14,.14);obj.position.y-=state.suspension||0;}return f;}
 render(state,dt,mode,options={}){
  this.totalTime+=dt;this.living.update(this.totalTime,state.s);this.details.update(this.totalTime,state.s);this.updateMascots(state,mode,options.encounters||[]);this.updateEffects(state,dt);
  const menu=mode==='menu',flight=['finish','results'].includes(mode),f=this.placeCar(this.car,options.motion===false?{...state,stagger:0,roll:0,pitch:0}:state),speed=state.speed||0;
  this.carShadow.position.copy(this.car.position);this.carShadow.position.y=f.p.y+.05;this.carShadow.material.opacity=.24/(1+state.air*.3);this.exhaust.visible=state.boosting;
  this.rally.update(state,dt,mode,options.challenge,options);this.hospitals.update(state,mode);
  let desired,target;if(flight){const angle=options.motion===false?0:Math.sin(Math.min(state.rocketAge,12)*.23)*.22,portrait=this.camera.aspect<.8;desired=this.car.position.clone().addScaledVector(f.t,portrait?-28:-19).addScaledVector(f.r,(portrait?18:12)+angle*8);desired.y+=7;target=this.car.position.clone();target.y+=3;if(portrait)target.addScaledVector(f.r,-4);}
  else if(menu){desired=f.p.clone().addScaledVector(f.t,-19).addScaledVector(f.r,10+(options.motion===false?0:Math.sin(this.totalTime*.12)*3));desired.y+=9;target=f.p.clone().addScaledVector(f.t,23);target.y+=2;}
  else if(state.sightseeing&&this.hospitals.items.some(h=>h.s>state.s+10&&h.s-state.s<300)){const h=this.hospitals.items.find(h=>h.s>state.s+10&&h.s-state.s<300);desired=this.car.position.clone().addScaledVector(f.t,-18).addScaledVector(f.r,-h.side*6);desired.y+=8;const focus=h.p.clone();focus.y=h.y+12;target=this.car.position.clone().addScaledVector(f.t,23);target.y+=1.5;target.lerp(focus,.86);}
  else if(options.camera==='hood'){desired=this.car.position.clone().addScaledVector(f.t,1.3);desired.y+=1.65;target=this.track.position(Math.min(state.s+60,this.track.roadLength),state.x*.5,2);}
  else{const heading=state.travelHeading??state.heading,velocity=f.t.clone().multiplyScalar(Math.cos(heading)).addScaledVector(f.r,Math.sin(heading));desired=this.car.position.clone().addScaledVector(velocity,-13-speed*.035);desired.y+=5.8+speed*.008;target=this.car.position.clone().addScaledVector(velocity,23+speed*.12);target.y+=1.5;target.lerp(this.track.position(Math.min(state.s+36+speed*.15,this.track.roadLength),state.x*.35,2),.28);}
  if(!this.cameraInitialized){this.camera.position.copy(desired);this.camTarget.copy(target);this.cameraInitialized=true;}else{this.camera.position.lerp(desired,1-Math.exp(-dt*(menu?2:flight?13:15)));this.camTarget.lerp(target,1-Math.exp(-dt*(flight?16:state.sightseeing?2.5:12)));}
  this.camera.lookAt(this.camTarget);const fov=options.motion===false||flight?62:62+speed*.065+(state.boosting?3:0);this.camera.fov+=(fov-this.camera.fov)*Math.min(1,dt*4);this.camera.updateProjectionMatrix();
  const texel=180/this.sun.shadow.mapSize.x;this.lightAnchor.copy(this.car.position);const rx=this.lightAnchor.dot(this.lightRight),uy=this.lightAnchor.dot(this.lightUp);this.lightAnchor.addScaledVector(this.lightRight,Math.round(rx/texel)*texel-rx).addScaledVector(this.lightUp,Math.round(uy/texel)*texel-uy);this.sun.position.copy(this.lightAnchor).add(this.lightOffset);this.sun.target.position.copy(this.lightAnchor);if(this.aurora)this.aurora.material.uniforms.time.value=this.totalTime;this.renderer.render(this.scene,this.camera);
 }
}
